<?php
defined('ABSPATH') || exit;
// phpcs:disable WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedVariableFound -- single-execution admin-page template, see admin/login-attempts.php
if (!AVPVH_Roles::can_view_dmarc()) {
    wp_die(esc_html__('Geen toegang.', 'avpvh-members'));
}

// The report itself is generated by dmarc-reports.py in docker-scripts,
// which stores it as the content of a page; this screen only shows it.
$page = WP_Post::get_instance((int) get_option(AVPVH_DMARC_PAGE_OPTION));
?>
<div class="wrap avpvh-dmarc">
    <h1><?php esc_html_e('DMARC-rapporten', 'avpvh-members'); ?></h1>
    <?php if (!$page || $page->post_type !== 'page' || $page->post_status === 'trash') : ?>
        <div class="notice notice-warning"><p><?php esc_html_e('Er is nog geen DMARC-rapport. Het wordt aangemaakt door het script dmarc-reports.py in de repository docker-scripts, dat dagelijks op de server draait.', 'avpvh-members'); ?></p></div>
    <?php else : ?>
        <p class="description"><?php echo esc_html(sprintf(
            /* translators: %s: date and time */
            __('Laatst gewijzigd: %s', 'avpvh-members'),
            wp_date('d-m-Y H:i', strtotime($page->post_modified_gmt . ' UTC'))
        )); ?></p>
        <?php echo wp_kses_post(preg_replace('/<!--\s*\/?wp:html\s*-->/', '', $page->post_content)); ?>
    <?php endif; ?>
</div>
